% MATLAB Reference Script for Free Convection Heat Transfer
Ts = 80;    % Surface temperature (deg C)
T_inf = 30; % Ambient temperature (deg C)
L = 0.5;    % Height of cylinder (m)

Tf_K = ((Ts + T_inf)/2) + 273.15;
beta = 1 / Tf_K;
nu = 1.6e-5;
k = 0.026;
Pr = 0.71;
g = 9.81;

Gr_L = (g * beta * abs(Ts - T_inf) * L^3) / (nu^2);
Ra_L = Gr_L * Pr;

Nu_L = (0.825 + (0.387 * Ra_L^(1/6)) / (1 + (0.492/Pr)^(9/16))^(8/27))^2;
h = Nu_L * k / L;

fprintf('h = %.3f W/m^2.K\n', h);
